package blockbranch.mixin.cubic;
import java.util.*;import blockbranch.realistic.*;import net.minecraft.core.Direction;import net.minecraft.world.level.ChunkPos;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.pieces.PiecesContainer;import net.minecraft.world.level.levelgen.structure.structures.*;import org.spongepowered.asm.mixin.Mixin;import com.llamalad7.mixinextras.injector.wrapmethod.WrapMethod;import com.llamalad7.mixinextras.injector.wrapoperation.Operation;
@Mixin(OceanMonumentStructure.class)
abstract class ReimaginedMonumentMixin {
 @WrapMethod(method="findGenerationPoint") private Optional<Structure.GenerationStub> blockbranch$layout(Structure.GenerationContext c,Operation<Optional<Structure.GenerationStub>> original){if(!(c.chunkGenerator() instanceof RealisticGenerator g)||g.reimaginedDefinition()==0)return original.call(c);return g.reimagined(c.randomState()).forStart(5,c.chunkPos().x(),c.chunkPos().z()).map(p->new Structure.GenerationStub(p.center(),b->{var direction=Direction.Plane.HORIZONTAL.getRandomDirection(c.random());var core=new OceanMonumentPieces.MonumentBuilding(c.random(),p.x()-29,p.z()-29,direction);ReimaginedSanctuaryPiece.fit(core,p.y());b.addPiece(core);b.addPiece(new ReimaginedSanctuaryPiece(core,g.reimaginedDefinition()>=3?1:0,g.sanctuaryReplacementDefinition()));}));}
 @WrapMethod(method="regeneratePiecesAfterLoad") private static PiecesContainer blockbranch$restore(ChunkPos pos,long seed,PiecesContainer saved,Operation<PiecesContainer> original){var marker=saved.pieces().stream().filter(p->p instanceof ReimaginedSanctuaryPiece).findFirst();var rebuilt=original.call(pos,seed,saved);if(marker.isEmpty())return rebuilt;if(saved.pieces().size()!=2||rebuilt.pieces().size()!=1||!(rebuilt.pieces().getFirst() instanceof OceanMonumentPieces.MonumentBuilding core))throw new IllegalArgumentException("Invalid saved sanctuary native graph");ReimaginedSanctuaryPiece.fit(core,saved.pieces().getFirst().getBoundingBox().minY());return new PiecesContainer(List.of(core,marker.orElseThrow()));}
}
